def _d(s):
    return datetime.date.fromisoformat(s) if s else None


def _t(s):
    if not s:
        return None
    try:
        return datetime.datetime.strptime(s, "%H:%M").time()
    except ValueError:
        return None


def reload_events(apps, schema_editor):
    LabEvent = apps.get_model("planning", "LabEvent")
    # on repart d'une base propre pour l'import automatique (idempotent)
    LabEvent.objects.filter(created_by="import@laspad.org").delete()
    rows = json.loads(base64.b64decode("".join(DATA_B64.split())).decode("utf-8"))
    for r in rows:
        LabEvent.objects.create(
            projet=r["projet"], type_event=r["type_event"], titre=r["titre"],
            description=r["description"], date_debut=_d(r["date_debut"]),
            heure=_t(r["heure"]), date_fin=_d(r["date_fin"]),
            responsable=r["responsable"], invites=r["invites"],
            besoins_com=r["besoins_com"], besoins_prod=r["besoins_prod"],
            lieu=r["lieu"], statut=r["statut"], budget=r["budget"],
            created_by="import@laspad.org",
        )


def unload_events(apps, schema_editor):
    LabEvent = apps.get_model("planning", "LabEvent")
    LabEvent.objects.filter(created_by="import@laspad.org").delete()


